from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    rects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny,nx))
            if len(cells) < 6:
                continue
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
            area = (r1-r0+1)*(c1-c0+1)
            # A colored rectangle with a few noisy cells replaced is restored in full.
            if area >= 6 and len(cells) / area >= 0.68:
                rects.append((r0,c0,r1,c1,color))
    out = [[background] * w for _ in range(h)]
    for r0,c0,r1,c1,color in rects:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                out[r][c] = color
    return out

